functions.handleCtrlA:
function handleCtrlA() {
    var features = selectedFeatures.getArray();
    if (features.length === 0) return;
    var anchor = features[0];
    var aProv = anchor.get('provenance') || {};
    var aFile = (aProv.file || '').replace(/\\/g, '/');
    var aLine = aProv.line;
    if (!aFile || !aLine || anchor.get('isDrawn')) { document.getElementById('workflow-status').textContent='No source reference to expand. Select instances directly.'; return; }
    var aInst = aProv.instance_name || '';
    var aVec = _idxVec(aProv);

    function sameLine(f) {
        var p = f.get('provenance') || {};
        return (p.file || '').replace(/\\/g, '/') === aFile && p.line === aLine;
    }
    var lineGroup = allFeatures.filter(sameLine);

    // Ladder of selection levels, innermost first:
    //   L1: same instance + full index vector (one loop iteration / one array
    //       element / one plain instance)
    //   L2..Ln: same placement line + index prefix (drop the innermost index
    //       each press — walk outward through nested loops / arrays)
    //   then: clear
    var levels = [];
    levels.push(function (f) {
        var p = f.get('provenance') || {};
        return p.instance_name === aInst && _vecPrefixEq(_idxVec(p), aVec, aVec.length);
    });
    for (var k = aVec.length - 1; k >= 0; k--) {
        (function (kk) {
            levels.push(function (f) {
                return _vecPrefixEq(_idxVec(f.get('provenance') || {}), aVec, kk);
            });
        })(k);
    }
    // Plain features (no loop/array indices): still offer a "whole placement
    // line" step after the instance level.
    if (aVec.length === 0) {
        levels.push(function (f) { return true; }); // within lineGroup
    }

    // Advance the cycle, skipping levels that wouldn't expand the selection.
    var level = selectionCycle; // 0-based next level index
    var matches = null;
    while (level < levels.length) {
        var cand = lineGroup.filter(levels[level]);
        if (cand.length > features.length) { matches = cand; break; }
        level++;
    }
    var cycleEl = document.getElementById('cycle-indicator');
    if (matches === null) {
        // Cycle complete: clear and reset
        rewriteLabels('');
        clearSelection();
        selectionCycle = 0;
        if (cycleEl) { cycleEl.textContent = ''; cycleEl.style.display = 'none'; }
    } else {
        replaceSelection(matches);
        selectionCycle = level + 1;
        rewriteLabels('[:]');
        if (cycleEl) {
            var kLabel = aVec.length === 0 ? level : aVec.length - level;
            cycleEl.textContent = 'L' + (level + 1) + ': ' + _levelLabel(aVec, kLabel) + '  Ctrl+A\u2192more';
            cycleEl.style.display = 'block';
        }
    }
    onSelectionChanged();
}

functions._selectFeaturesBySource:
function _selectFeaturesBySource(targetFile, targetLine) {
    targetFile = (targetFile || '').replace(/\\/g, '/');
    targetLine = parseInt(targetLine, 10);
    if (!targetFile || isNaN(targetLine)) return;

    var matches = allFeatures.filter(function(f) {
        var prov = f.get('provenance') || {};
        var fFile = (prov.resolved_file || prov.file || '').replace(/\\/g, '/');
        var fBase = fFile.split('/').pop() || '';
        var tBase = targetFile.split('/').pop() || '';
        if (fFile.toLowerCase() !== targetFile.toLowerCase()) return false;
        var fLine = typeof prov.line === 'number' ? prov.line : parseInt(String(prov.line), 10);
        return fLine === targetLine;
    });

    // Also check call_chain entries
    var chainMatches = allFeatures.filter(function(f) {
        var prov = f.get('provenance') || {};
        var chain = prov.call_chain || [];
        return chain.some(function(cc) {
            var ccFile = (cc.resolved_file || cc.file || '').replace(/\\/g, '/');
            var ccBase = ccFile.split('/').pop() || '';
            var tBase = targetFile.split('/').pop() || '';
            if (ccFile.toLowerCase() !== targetFile.toLowerCase()) return false;
            var ccLine = typeof cc.line === 'number' ? cc.line : parseInt(String(cc.line), 10);
            return ccLine === targetLine;
        });
    });

    // Merge, deduplicate by ol_uid
    var seen = {};
    var all = [];
    matches.concat(chainMatches).forEach(function(f) {
        if (!seen[f.ol_uid]) {
            seen[f.ol_uid] = true;
            all.push(f);
        }
    });

    if (all.length > 0) {
        replaceSelection(all);
        onSelectionChanged();
        var extent = all[0].getGeometry().getExtent().slice(0);
        for (var i = 1; i < all.length; i++) {
            ol.extent.extend(extent, all[i].getGeometry().getExtent());
        }
        map.getView().fit(extent, { padding: [60, 60, 60, 60], duration: 300 });
    }
}
